contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint putAmount, uint collectAmount) public payable {
        require(address(this).balance >= putAmount);

        c.Put{value: putAmount}(lockTime);

        (uint unlockTimeBefore, uint balanceBefore) = c.Acc();
        uint cBalanceBefore = address(c).balance;
        uint thisBalanceBefore = address(this).balance;

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint unlockTimeAfter, uint balanceAfter) = c.Acc();
        uint cBalanceAfter = address(c).balance;
        uint thisBalanceAfter = address(this).balance;

        if (!reverted) {
            assert(balanceBefore >= collectAmount);
            assert(unlockTimeBefore < block.timestamp);
            assert(balanceAfter == balanceBefore - collectAmount);
            assert(thisBalanceAfter == thisBalanceBefore + collectAmount);
            assert(cBalanceBefore == cBalanceAfter + collectAmount);
            assert(cBalanceAfter == cBalanceBefore - collectAmount);
        } else {
            assert(unlockTimeAfter == unlockTimeBefore);
            assert(balanceAfter == balanceBefore);
            assert(cBalanceAfter == cBalanceBefore);
            assert(thisBalanceAfter == thisBalanceBefore);
        }
    }

    receive() external payable {}
}

