contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint putVal, uint minSum, uint collectAmt) public payable {
        require(address(this).balance >= putVal + collectAmt);

        c.SetMinSum(minSum);
        c.Initialized();
        c.Put{value: putVal}(lockTime);

        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        if (beforeBal >= minSum && beforeBal >= collectAmt && block.timestamp > beforeUnlock) {
            bool reverted;
            try c.Collect{value: collectAmt}(collectAmt) {
                reverted = false;
            } catch {
                reverted = true;
            }

            (uint afterUnlock, uint afterBal) = c.Acc(address(this));
            uint afterContractBal = address(c).balance;

            if (!reverted) {
                assert(afterBal == beforeBal - collectAmt && afterContractBal == beforeContractBal - collectAmt);
            } else {
                assert(afterBal == beforeBal && afterContractBal == beforeContractBal);
            }
        } else {
            assert(beforeBal == putVal && beforeContractBal == putVal);
        }
    }

    receive() external payable {}
}

