    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint putAmount, uint minSum, uint collectAmount)
        public
        payable
    {
        require(address(this).balance >= putAmount);

        c.SetMinSum(minSum);
        c.Put{value: putAmount}(lockTime);

        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(this));
        uint minSumBefore = c.MinSum();

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool expectedSuccess = balanceBefore >= minSumBefore
            && balanceBefore >= collectAmount
            && block.timestamp > unlockTimeBefore;

        assert(reverted == !expectedSuccess);
    }

    receive() external payable {}
}

