contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint putAmount, uint lockTime, uint minSum, uint collectAmount) public payable {
        require(address(this).balance >= putAmount, "insufficient test balance");
        require(minSum <= putAmount, "minSum too high for test scenario");
        require(collectAmount <= putAmount, "collect amount too high for test scenario");

        c.SetMinSum(minSum);
        c.SetLogFile(address(this));
        c.Initialized();

        c.Put{value: putAmount}(lockTime);

        (uint unlockTime, uint balanceBefore) = c.Acc(address(this));

        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        if (!collectReverted) {
            (, uint balanceAfter) = c.Acc(address(this));
            assert(balanceAfter == balanceBefore - collectAmount);
        } else {
            assert(
                balanceBefore < minSum ||
                balanceBefore < collectAmount ||
                block.timestamp <= unlockTime
            );
        }
    }

    receive() external payable {}
}
